import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import PageStructure from 'flarum/forum/components/PageStructure';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import extractText from 'flarum/common/utils/extractText';
import { boards } from '../../common/api';
import { t } from '../../common/format';
import { ArtistList, ListenerList, TrackList } from '../components/Lists';
const c = (key, params = {}) => app.translator.trans(`ernestdefoe-rotation.forum.charts.${key}`, params);

/** /rotation — the forum's songs, artists and listeners. */
export default class ChartsPage extends Page {
  tab = 'tracks';
  period = 'week';
  rows = {};
  loading = false;
  oninit(vnode) {
    super.oninit(vnode);
    app.setTitle(extractText(c('title')));
    this.load();
  }
  load() {
    this.loading = true;
    boards([this.tab], this.period, 50).then(res => this.rows = res.data).catch(() => this.rows = {}).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
  view() {
    const rows = this.rows[this.tab];
    const list = {
      tracks: TrackList,
      artists: ArtistList,
      listeners: ListenerList
    }[this.tab];
    return m(PageStructure, {
      className: "RotationChartsPage",
      sidebar: () => m(IndexSidebar, null)
    }, m("h2", {
      className: "RotationChartsPage-title"
    }, m("i", {
      className: "fas fa-compact-disc",
      "aria-hidden": "true"
    }), " ", c('title')), m("div", {
      className: "RotationChartsPage-controls"
    }, m("div", {
      className: "ButtonGroup"
    }, ['tracks', 'artists', 'listeners'].map(tab => m(Button, {
      className: 'Button' + (this.tab === tab ? ' active' : ''),
      onclick: () => this.select(tab, this.period)
    }, c(tab)))), m("div", {
      className: "ButtonGroup"
    }, ['week', 'month', 'year', 'all'].map(period => m(Button, {
      className: 'Button Button--small' + (this.period === period ? ' active' : ''),
      onclick: () => this.select(this.tab, period)
    }, t(`period.${period}`))))), this.loading ? m(LoadingIndicator, null) : rows && rows.length ? list(rows) : m("p", {
      className: "RotationEmpty"
    }, c('empty')), m("p", {
      className: "helpText RotationChartsPage-help"
    }, c('help')));
  }
  select(tab, period) {
    if (tab === this.tab && period === this.period) return;
    this.tab = tab;
    this.period = period;
    this.load();
  }
}
flarum.reg.add('ernestdefoe-rotation', 'forum/pages/ChartsPage', ChartsPage);